import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 미승인 근태 신청이 있으면 마감할 수 없다 (422)
// 가정: 월 마감의 마감 대상 일자는 해당 월 1일로 저장한다
const UNITS = ['일', '월'];
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

// 마감 기간 시작일·종료일 (파라미터: unit, d)
const PERIOD_SQL = `
  WITH p AS (
    SELECT
      CASE WHEN CAST(:unit AS text) = '일'
        THEN CAST(:d AS date)
        ELSE CAST(date_trunc('month', CAST(:d AS date)) AS date)
      END AS s
  ), q AS (
    SELECT
      s,
      CASE WHEN CAST(:unit AS text) = '일'
        THEN s
        ELSE CAST(s + interval '1 month' - interval '1 day' AS date)
      END AS e
    FROM p
  )
`;

function readClosingInput(source: Record<string, unknown>) {
  const closingUnit = source['closingUnit'];
  const closingDate = source['closingDate'];
  if (typeof closingUnit !== 'string' || !UNITS.includes(closingUnit)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '마감 단위는 일 또는 월이어야 합니다.');
  }
  if (typeof closingDate !== 'string' || !DATE_PATTERN.test(closingDate)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '마감 대상 일자를 YYYY-MM-DD 형식으로 입력해 주세요.');
  }
  return { unit: closingUnit, d: closingDate };
}

@Controller('api/v1')
export class FnSfr01807Controller {
  @Get('/attendance-closings/preview')
  async previewAttendanceClosing(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자');
    const q = checks.queryOf(req.query);
    const params = readClosingInput(q);
    return transaction(async (db) => {
      const closed = await db.query(
        `${PERIOD_SQL}
         SELECT 1 AS found
         FROM attendance_closing c, q
         WHERE c.closing_unit = CAST(:unit AS text)
           AND c.closing_date = q.s
           AND c.status = '마감'`,
        params,
      );
      if (closed.length > 0) {
        throw new ApiError(409, 'ATTENDANCE_ALREADY_CLOSED', '이미 마감된 기간입니다.');
      }
      const rows = await db.query(
        `${PERIOD_SQL}
         SELECT
           (SELECT COUNT(*) FROM attendance_request r
             WHERE r.approval_status = '신청'
               AND r.start_date <= q.e AND r.end_date >= q.s) AS "unapprovedCount",
           (SELECT COUNT(*) FROM commute_record m
             WHERE m.work_date >= q.s AND m.work_date <= q.e) AS "recordCount"
         FROM q`,
        params,
      );
      return {
        unapprovedCount: Number(rows[0].unapprovedCount),
        recordCount: Number(rows[0].recordCount),
      };
    });
  }

  @Post('/attendance-closings')
  @HttpCode(200)
  async createAttendanceClosing(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자');
    const data = checks.inputOf(req.body);
    const params = readClosingInput(data);
    return transaction(async (db) => {
      const existing = await db.query(
        `${PERIOD_SQL}
         SELECT c.attendance_closing_id AS "attendanceClosingId", c.status AS "status"
         FROM attendance_closing c, q
         WHERE c.closing_unit = CAST(:unit AS text)
           AND c.closing_date = q.s`,
        params,
      );
      if (existing.length > 0 && existing[0].status === '마감') {
        throw new ApiError(409, 'ATTENDANCE_ALREADY_CLOSED', '이미 마감된 기간입니다.');
      }
      const unapproved = await db.query(
        `${PERIOD_SQL}
         SELECT COUNT(*) AS "cnt"
         FROM attendance_request r, q
         WHERE r.approval_status = '신청'
           AND r.start_date <= q.e AND r.end_date >= q.s`,
        params,
      );
      if (Number(unapproved[0].cnt) > 0) {
        throw new ApiError(422, 'UNAPPROVED_REQUEST_EXISTS', '미승인 근태 신청이 있어 마감할 수 없습니다.');
      }
      let rows;
      if (existing.length > 0) {
        rows = await db.query(
          `UPDATE attendance_closing
           SET status = '마감', closed_at = now(), cancelled_at = NULL, updated_at = now()
           WHERE attendance_closing_id = CAST(:id AS bigint)
           RETURNING attendance_closing_id AS "attendanceClosingId", status AS "status", closed_at AS "closedAt"`,
          { id: String(existing[0].attendanceClosingId) },
        );
      } else {
        rows = await db.query(
          `${PERIOD_SQL}
           INSERT INTO attendance_closing
             (closing_unit, closing_date, status, closed_at, created_at, updated_at)
           SELECT CAST(:unit AS text), q.s, '마감', now(), now(), now() FROM q
           RETURNING attendance_closing_id AS "attendanceClosingId", status AS "status", closed_at AS "closedAt"`,
          params,
        );
      }
      await db.execute(
        `${PERIOD_SQL}
         UPDATE commute_record
         SET is_closed = true, updated_at = now()
         FROM q
         WHERE commute_record.work_date >= q.s AND commute_record.work_date <= q.e`,
        params,
      );
      return rows[0];
    });
  }

  @Post('/attendance-closings/:attendanceClosingId/cancel')
  @HttpCode(200)
  async cancelAttendanceClosing(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자');
    const id = req.params['attendanceClosingId'];
    if (!/^\d+$/.test(id)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '근태 마감 ID 형식이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT status AS "status"
         FROM attendance_closing
         WHERE attendance_closing_id = CAST(:id AS bigint)`,
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'ATTENDANCE_CLOSING_NOT_FOUND', '마감 건을 찾을 수 없습니다.');
      }
      if (found[0].status !== '마감') {
        throw new ApiError(409, 'ATTENDANCE_NOT_CLOSED', '마감 상태가 아닙니다.');
      }
      await db.execute(
        `UPDATE commute_record
         SET is_closed = false, updated_at = now()
         WHERE EXISTS (
           SELECT 1 FROM attendance_closing c
           WHERE c.attendance_closing_id = CAST(:id AS bigint)
             AND commute_record.work_date >= c.closing_date
             AND commute_record.work_date <= CASE WHEN c.closing_unit = '일'
               THEN c.closing_date
               ELSE CAST(c.closing_date + interval '1 month' - interval '1 day' AS date)
             END
         )`,
        { id },
      );
      const rows = await db.query(
        `UPDATE attendance_closing
         SET status = '마감 취소', cancelled_at = now(), updated_at = now()
         WHERE attendance_closing_id = CAST(:id AS bigint)
         RETURNING attendance_closing_id AS "attendanceClosingId", status AS "status", cancelled_at AS "cancelledAt"`,
        { id },
      );
      return rows[0];
    });
  }
}

