import { useState } from 'react';
import {
  call,
  Badge,
  Band,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  Field,
  Form,
  Select,
  Tiles,
  Num,
} from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr01807Page({ role, notify }: PageProps) {
  // 조회 API가 없어 이 화면에서 처리한 마감 결과를 목록으로 보인다
  const [results, setResults] = useState<Row[]>([]);
  const [creating, setCreating] = useState(false);
  const [cancelTarget, setCancelTarget] = useState<Row | null>(null);
  const [unit, setUnit] = useState('');
  const [date, setDate] = useState('');
  const [preview, setPreview] = useState<Row | null>(null);
  const [previewError, setPreviewError] = useState('');

  function openCreate() {
    setUnit('');
    setDate('');
    setPreview(null);
    setPreviewError('');
    setCreating(true);
  }

  function validate() {
    if (!unit) throw new Error('마감 단위를 선택해 주세요.');
    if (!date) throw new Error('마감 대상 일자를 입력해 주세요.');
  }

  async function loadPreview() {
    setPreview(null);
    setPreviewError('');
    try {
      validate();
      const res = await call('GET', '/attendance-closings/preview', role, undefined, {
        closingUnit: unit,
        closingDate: date,
      });
      setPreview(res);
    } catch (e) {
      setPreviewError(e instanceof Error ? e.message : '미리보기에 실패했습니다.');
    }
  }

  async function submitCreate() {
    validate();
    const res = await call('POST', '/attendance-closings', role, {
      closingUnit: unit,
      closingDate: date,
    });
    const row: Row = {
      attendanceClosingId: res.attendanceClosingId,
      closingUnit: unit,
      closingDate: date,
      status: res.status,
      closedAt: res.closedAt,
    };
    setResults((prev) => [row, ...prev.filter((r) => r.attendanceClosingId !== row.attendanceClosingId)]);
    setCreating(false);
    notify('근태를 마감했습니다.');
  }

  async function submitCancel() {
    if (!cancelTarget) return;
    const id = cancelTarget.attendanceClosingId;
    const res = await call('POST', `/attendance-closings/${id}/cancel`, role, {});
    setResults((prev) =>
      prev.map((r) => (r.attendanceClosingId === id ? { ...r, status: res.status } : r)),
    );
    setCancelTarget(null);
    notify('근태 마감을 취소했습니다.');
  }

  return (
    <div>
      <h1>근태 확정 관리</h1>
      <Band total={results.length}>
        <button onClick={openCreate}>근태 마감</button>
      </Band>
      <DataTable
        rows={results}
        empty='아직 마감한 내역이 없습니다. 근태 마감 버튼을 눌러 시작해 주세요.'
        columns={[
          { key: 'attendanceClosingId', label: '근태 마감 ID' },
          { key: 'closingUnit', label: '마감 단위' },
          {
            key: 'closingDate',
            label: '마감 대상 일자',
            render: (r) => <DateText value={r.closingDate} />,
          },
          { key: 'status', label: '마감 상태', render: (r) => <Badge value={r.status} /> },
          {
            key: 'action',
            label: '처리',
            render: (r) =>
              r.status === '마감' ? (
                <button className='ghost' onClick={() => setCancelTarget(r)}>
                  마감 취소
                </button>
              ) : null,
          },
        ]}
      />
      {creating && (
        <Drawer title='근태 마감' onClose={() => setCreating(false)}>
          <Form
            submit='마감 실행'
            onSubmit={submitCreate}
            note='마감한 기간의 데이터는 마감을 취소하기 전에는 수정할 수 없습니다.'
          >
            <Field label='마감 단위' required>
              <Select
                value={unit}
                onChange={setUnit}
                options={[
                  ['일', '일'],
                  ['월', '월'],
                ]}
              />
            </Field>
            <Field label='마감 대상 일자' required hint='월 마감은 해당 월의 날짜를 고르면 됩니다.'>
              <DateInput value={date} onChange={setDate} />
            </Field>
          </Form>
          <button className='ghost' onClick={loadPreview}>
            집계 미리보기
          </button>
          {previewError && <p>{previewError}</p>}
          {preview && (
            <Tiles
              items={[
                ['미승인 근태 신청 건수', <Num value={preview.unapprovedCount} />],
                ['집계 대상 출퇴근 기록 건수', <Num value={preview.recordCount} />],
              ]}
            />
          )}
        </Drawer>
      )}
      {cancelTarget && (
        <Drawer title='근태 마감 취소' onClose={() => setCancelTarget(null)}>
          <Form
            submit='마감 취소'
            danger
            onSubmit={submitCancel}
            note='취소하면 해당 기간의 근태 데이터를 다시 수정할 수 있게 됩니다.'
          >
            <p>
              {String(cancelTarget.closingUnit)} 마감 ({String(cancelTarget.closingDate)})을 취소합니다.
            </p>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
